ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from dwl::SfdcResponseNormalizer
var records = payload map ((item) -> item mapObject ((v, k) ->
    if (k as String == "attributes") {} else {(k): v}
))
---
{
    success: true,
    data: {
        records: records,
        totalSize: sizeOf(records)
    },
    metadata: {
        operation: "query",
        recordCount: sizeOf(records),
        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"},
        correlationId: correlationId,
        apiVersion: p('sfdc.api.version'),
        queryComplexity: vars.queryComplexity
    }
}
